# owner: platform
"""Seating charts: students sorted by last name, in rows."""


def _name_key(student):
    last = student.last_name.lower()
    first = student.first_name.lower()
    return (last, first)


def _label(student):
    return f"{student.last_name}, {student.first_name}"


def _line(number, group):
    names = " | ".join(map(_label, group))
    return f"Row {number}: {names}"


# ---
def seat_rows(students, per_row):
    if per_row <= 0 or not students:
        raise ValueError("need students and seats")
    ordered = sorted(students, key=_name_key)
    rows = [ordered[start:start + per_row]
            for start in range(0, len(ordered), per_row)]
    return [_line(*pair) for pair in enumerate(rows, 1)]

