# owner: platform
import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student


def _pupil(last, first):
    return Student("id", last, first, "A")


class SeatRowsTests(unittest.TestCase):
    # ---
    def test_sorts_and_fills_rows(self):
        pupils = [
            _pupil("Halloway", "Juno"),
            _pupil("Zed", "Amy"),
            _pupil("Dunmere", "Piet"),
        ]
        self.assertEqual(
            seat_rows(pupils, 2),
            ["Row 1: Dunmere, Piet | Halloway, Juno",
             "Row 2: Zed, Amy"],
        )

    # ---
    def test_bad_seat_count_raises(self):
        pupils = [_pupil("Zed", "Amy")]
        for count in (0, -1):
            with self.assertRaises(ValueError):
                seat_rows(pupils, count)

    # ---
    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seat_rows([], 3)
